SELECT mp.id AS id, mp.product_name AS itemName, mp.product_code AS itemCode, mp.product_seq AS itemSeq, mw.id AS existItem FROM micro_product mp LEFT JOIN micro_work_submit mw ON mp.tenant_code = mw.tenant_code AND mp.product_seq = mw.product_seq WHERE mp.id in
#{id}
UNION SELECT mp.id AS id, mp.product_name AS itemName, mp.product_code AS itemCode, mp.product_seq AS itemSeq, IF( mt.id IS NULL, NULL, 1 ) AS existItem FROM micro_product mp LEFT JOIN micro_technology mt ON mp.tenant_code = mt.tenant_code AND mp.id = mt.product_id WHERE mp.id in
#{id}
UNION SELECT mp.id AS id, mp.product_name AS itemName, mp.product_code AS itemCode, mp.product_seq AS itemSeq, IF( mmwo.id IS NULL, NULL, 1 ) AS existItem FROM micro_product mp LEFT JOIN micro_manufacture_work_order mmwo ON mp.tenant_code = mmwo.tenant_code AND mp.product_seq = mmwo.product_seq WHERE mp.id in
#{id}
UNION SELECT mp.id AS id, mp.product_name AS itemName, mp.product_code AS itemCode, mp.product_seq AS itemSeq, IF( t.stockOrNot = 1, 1, NULL ) AS existItem FROM micro_product mp LEFT JOIN ( SELECT mps.tenant_code, mps.product_seq, IF ( sum( mps.pass_num ) = 0 AND sum( mps.ng_num )= 0, 0, 1 ) AS stockOrNot FROM micro_process_storage mps GROUP BY mps.tenant_code, mps.product_seq ) AS t ON mp.tenant_code = t.tenant_code AND mp.product_seq = t.product_seq WHERE mp.id IN
#{id}

select mws.id, mws.tenant_code, mws.product_seq, mp.id as product_id, mp.product_name, mp.product_code, mp.unit, mws.pre_process_seq, (SELECT GROUP_CONCAT(mpc.process_name) FROM micro_process_common mpc where FIND_IN_SET(mpc.process_seq, mws.pre_process_seq) and mpc.tenant_code = mws.tenant_code) as pre_process_name, (SELECT GROUP_CONCAT(mpc.process_code) FROM micro_process_common mpc where FIND_IN_SET(mpc.process_seq, mws.pre_process_seq) and mpc.tenant_code = mws.tenant_code) as pre_process_code, mws.operate_process_seq, mpc2.process_name as operate_process_name, mpc2.process_code as operate_process_code, mws.pre_process_group, mws.operate_process_group, mws.is_last_process, mws.pass_num, mws.ng_num, mws.submit_user, mws.submit_day, mws.submit_status, mws.submit_no, mws.remark, mws.created_by, mws.created_date, mws.check_user, mws.check_date, mws.check_pass_num, mws.check_ng_num, mws.last_upd_by, mws.last_upd_date, mws.data_status, mws.expired_record_flag, mws.submit_pictures, mu.nick_name as submit_nick_name, mws.is_first_process, mws.check_status, mws.repair_num, mws.abandoned_num from micro_work_submit mws left join micro_product mp on mp.product_seq = mws.product_seq and mp.tenant_code = mws.tenant_code left join micro_process_common mpc2 on mpc2.process_seq = mws.operate_process_seq and mpc2.tenant_code = mws.tenant_code left join micro_user mu on mu.id = mws.submit_user
mws.id in
#{id}
and mu.nick_name like concat('%', #{submitNickName}, '%')
and mws.submit_status = #{submitStatus}
order by mws.id desc

