SELECT ifnull(sum(a.total_counts),0) as total_counts, ifnull(sum(a.total_pass_num),0) as total_pass_num, ifnull(sum(a.total_ng_num),0) as total_ng_num, a.submit_day FROM (SELECT ifnull(sum(check_pass_num + check_ng_num),0) as total_counts, ifnull(sum(check_pass_num),0) as total_pass_num, ifnull(sum(check_ng_num),0) as total_ng_num, submit_day FROM micro_work_submit
submit_status = '0' and submit_type = #{submitType}
and submit_day in
#{date}
and created_by = #{userId}
GROUP BY submit_day UNION SELECT ifnull(sum(pass_num + ng_num),0) as total_counts, ifnull(sum(pass_num),0) as total_pass_num, ifnull(sum(ng_num),0) as total_ng_num, submit_day FROM micro_work_submit
submit_status in ('1', '2') and submit_type = #{submitType}
and submit_day in
#{date}
and created_by = #{userId}
GROUP BY submit_day) a GROUP BY a.submit_day

SELECT ifnull(sum(a.total_counts),0) as total_counts, ifnull(sum(a.total_pass_num),0) as total_pass_num, ifnull(sum(a.total_ng_num),0) as total_ng_num, a.submit_day FROM (SELECT ifnull(sum(check_pass_num + check_ng_num),0) as total_counts, ifnull(sum(check_pass_num),0) as total_pass_num, ifnull(sum(check_ng_num),0) as total_ng_num, submit_day FROM micro_work_submit
submit_type = '1' and submit_status = '0'
and created_by = #{userId}
and submit_day BETWEEN #{startDayOfMonth} and #{endDayOfMonth}
GROUP BY submit_day UNION SELECT ifnull(sum(pass_num + ng_num),0) as total_counts, ifnull(sum(pass_num),0) as total_pass_num, ifnull(sum(ng_num),0) as total_ng_num, submit_day FROM micro_work_submit
submit_type = '1' and submit_status in ('1', '2')
and created_by = #{userId}
and submit_day BETWEEN #{startDayOfMonth} and #{endDayOfMonth}
GROUP BY submit_day) a GROUP BY a.submit_day

SELECT DISTINCT
mws.operate_process_seq,
mpc.process_name as operate_process_name,
mpc.process_code as operate_process_code
FROM micro_work_submit mws
left join micro_process_common mpc on mpc.process_seq = mws.operate_process_seq and mws.tenant_code=mpc.tenant_code

    mws.submit_type = '1'
    and mws.product_seq = #{productSeq}
    and mws.is_last_process = #{isLastProcess}
    and mws.is_first_process = #{isFirstProcess}
    and mws.submit_status = #{submitStatus}

order by mws.id desc

select mp.product_name, mp.product_code, mpc.process_name as operate_process_name, mws.product_seq, ifnull(sum(mws.check_pass_num),0) as check_pass_num, ifnull(sum(mws.check_ng_num),0) as check_ng_num from micro_work_submit mws left join micro_product mp on mws.product_seq = mp.product_seq and mws.tenant_code=mp.tenant_code left join micro_process_common mpc on mws.operate_process_seq = mpc.process_seq and mws.tenant_code=mpc.tenant_code
and mws.submit_type = #{submitType} and mws.submit_status = #{submitStatus}
and (mp.product_code like concat('%', #{productNameOrCode}, '%') or mp.product_name like concat('%', #{productNameOrCode}, '%'))
and (mpc.process_code like concat('%', #{processNameOrCode}, '%') or mpc.process_name like concat('%', #{processNameOrCode}, '%'))
and date_format(mws.submit_day, '%Y-%m-%d') >= date_format(#{startDate},'%Y-%m-%d') and date_format(mws.submit_day, '%Y-%m-%d') <= date_format(#{endDate},'%Y-%m-%d') and mws.product_seq = #{productSeq} and mws.operate_process_seq = #{operateProcessSeq}
group by mws.product_seq, mws.operate_process_seq

select distinct
submit_user as submitUser,
submit_day as submitDay
from micro_work_submit

    submit_type = '1'
    and submit_day >= #{startDate}
    and submit_day <= #{endDate}
    and submit_user = #{submitUser}

group by submit_user, submit_day

SELECT IFNULL(sum(check_pass_num + check_ng_num), 0) / count(1) as avgSubmitNum
FROM micro_work_submit
WHERE submit_status = '0'
  and submit_type = '1'
  and submit_user = #{submitUser}
  and product_seq = #{productSeq}
  and operate_process_seq = #{processSeq}
GROUP BY submit_user, product_seq, operate_process_seq
HAVING count(1) > 10

SELECT
min(is_last_process) as isLastProcess,
min(is_first_process) as isFirstProcess
FROM micro_work_submit

    submit_type = '1'
    and product_seq = #{productSeq}
    and operate_process_seq = #{processSeq}
    and submit_status = #{submitStatus}

