SELECT
SUM(IFNULL(a.total_num, 0)) as totalSubmitNum,
group_concat(ids) as ids
FROM
(
SELECT
SUM(IFNULL(check_pass_num, 0)) + SUM(IFNULL(check_ng_num, 0)) AS total_num,
group_concat(id) as ids
FROM
micro_work_submit

    submit_type = '1'
    and submit_status = 0

        and submit_user = #{submitUser}


        and product_seq = #{productSeq}


        and operate_process_seq = #{operateProcessSeq}


        and submit_day = #{submitDay}


UNION ALL
SELECT
SUM(IFNULL(pass_num, 0)) + SUM(IFNULL(ng_num, 0))AS total_num,
group_concat(id) as ids
FROM
micro_work_submit

    submit_type = '1'
    and submit_status = 1

        and submit_user = #{submitUser}


        and product_seq = #{productSeq}


        and operate_process_seq = #{operateProcessSeq}


        and submit_day = #{submitDay}


) a

SELECT a.product_seq, a.operate_process_seq, mpc.process_code as operate_process_code, mpc.process_name as operate_process_name, min(a.is_last_process) as is_last_process, a.unit as product_unit, a.submit_user as user_id, mu.nick_name, sum(a.pass_num) as pass_num, sum(a.ng_num ) as ng_num, group_concat(a.id) as ids FROM (SELECT mws.id, mws.operate_process_seq, mws.submit_user,
mws.pass_num as pass_num, mws.ng_num as ng_num,
mws.check_pass_num as pass_num, mws.check_ng_num as ng_num,
mws.is_last_process, mp.unit, mp.product_seq FROM micro_work_submit mws INNER join micro_product mp on mws.product_seq = mp.product_seq
mws.submit_type = '2'
and mws.work_order_no = #{workOrderNo}
and mws.submit_status = #{submitStatus}
) a INNER JOIN micro_user mu ON a.submit_user = mu.id INNER JOIN micro_process_common mpc ON a.operate_process_seq = mpc.process_seq GROUP BY operate_process_seq, submit_user

SELECT mws.id, mws.created_date as createdDate,
mws.pass_num as passNum, mws.ng_num as ngNum,
mws.check_pass_num as passNum, mws.check_ng_num as ngNum,
mws.submit_user as userId, mu.nick_name as nickName FROM micro_work_submit mws left join micro_user mu on mws.submit_user = mu.id
mws.submit_type = '2'
and mws.work_order_no = #{workOrderNo}
and mws.operate_process_seq = #{processSeq}
and mws.submit_status = #{submitStatus}
and mws.submit_user in
#{userId}

SELECT CASE submit_status WHEN 1 THEN 'waitCheckRecordNum' WHEN 2 THEN 'rejectRecordNum' ELSE 'checkRecordNum' END AS statusKey, count( 1 ) AS num FROM micro_work_submit
and submit_type = #{submitType} and submit_user = #{submitUser}
GROUP BY submit_status

SELECT mws.product_seq as productSeq, mp.product_code as productCode, mp.product_name as productName, mws.operate_process_seq as processSeq, mpc.process_name as processName, mws.submit_user as submitUser, mu.nick_name as submitNickName, sum( mws.check_ng_num ) - sum( mws.repair_num ) - sum( mws.abandoned_num ) AS ngNum FROM micro_work_submit mws LEFT JOIN micro_process_common mpc ON mws.operate_process_seq = mpc.process_seq and mws.tenant_code = mpc.tenant_code LEFT JOIN micro_product mp ON mws.product_seq = mp.product_seq and mws.tenant_code = mp.tenant_code LEFT JOIN micro_user mu on mu.id = mws.submit_user and mws.tenant_code = mu.tenant_code
mws.submit_status = 0
and mws.product_seq = #{productSeq}
and mws.operate_process_seq = #{processSeq}
GROUP BY mws.submit_user HAVING ngNum > 0 ORDER BY ngNum DESC

SELECT mws.product_seq as productSeq, mp.product_code as productCode, mp.product_name as productName, mp.unit as productUnit, mws.operate_process_seq as processSeq, mpc.process_name as processName, mws.submit_user as submitUser, sum(check_ng_num) - sum(repair_num) - sum(abandoned_num) as ngNum FROM micro_work_submit mws LEFT JOIN micro_product mp ON mws.product_seq = mp.product_seq and mws.tenant_code = mp.tenant_code LEFT JOIN micro_process_common mpc ON mws.operate_process_seq = mpc.process_seq and mws.tenant_code = mpc.tenant_code
mws.submit_status = 0
and mws.submit_user in
#{item}
and mws.submit_type = #{submitType}
GROUP BY mws.submit_user, mws.product_seq, mws.operate_process_seq HAVING ngNum > 0 ORDER BY ngNum desc

select mws.id, mws.tenant_code, mws.work_order_no, mws.task_no, mws.submit_type, mws.product_seq, mp.product_name, mp.product_code, mp.unit, mws.operate_process_seq, mpc.process_name as operate_process_name, mpc.process_code as operate_process_code, -- mws.pre_process_seq, -- (SELECT GROUP_CONCAT(mpc.process_name) FROM micro_process_common mpc where FIND_IN_SET(mpc.process_seq, mws.pre_process_seq) and mpc.tenant_code = mws.tenant_code) as pre_process_name, -- (SELECT GROUP_CONCAT(mpc.process_code) FROM micro_process_common mpc where FIND_IN_SET(mpc.process_seq, mws.pre_process_seq) and mpc.tenant_code = mws.tenant_code) as pre_process_code, mws.is_last_process, mws.pass_num, mws.ng_num, mws.submit_user, mu.nick_name as submit_nick_name, mws.submit_day, mws.submit_status, mws.submit_no, mws.remark, mws.created_by, mws.created_date, mws.check_user, mws.check_date, mws.check_pass_num, mws.check_ng_num, mws.data_status, mws.expired_record_flag, mws.submit_pictures, mws.is_first_process, mws.is_complete, mws.check_status, mws.repair_num, mws.abandoned_num from micro_work_submit mws left join micro_product mp on mp.product_seq = mws.product_seq and mp.tenant_code = mws.tenant_code left join micro_process_common mpc on mpc.process_seq = mws.operate_process_seq and mpc.tenant_code = mws.tenant_code left join micro_user mu on mws.submit_user = mu.id and mu.tenant_code = mws.tenant_code
mws.submit_status = 0
and mws.product_seq = #{productSeq}
and mws.operate_process_seq = #{operateProcessSeq}
and mws.submit_user = #{submitUser}
and mws.id in
