order by mws.created_date asc

SELECT * FROM ( SELECT mpc.process_seq AS itemSeq, mpc.process_name AS itemName, mpc.process_code AS itemCode, mpc.id AS itemId FROM micro_work_submit mws INNER JOIN micro_process_common mpc ON mpc.tenant_code = mws.tenant_code AND mpc.process_seq =mws.operate_process_seq WHERE mpc.id IN
#{id}
UNION SELECT mpc.process_seq AS itemSeq, mpc.process_name AS itemName, mpc.process_code AS itemCode, mpc.id as itemId FROM micro_work_submit mws INNER JOIN micro_process_common mpc on mpc.tenant_code = mws.tenant_code and FIND_IN_SET(mpc.process_seq, mws.pre_process_seq) WHERE mpc.id in
#{id}
) AS t WHERE t.itemId IS NOT NULL

SELECT a.product_seq as productSeq, a.product_code as productCode, a.product_name as productName, a.product_unit as productUnit, sum(a.pass_num) + sum(a.ng_num) as totalNum FROM (SELECT mws.product_seq, mp.product_code, mp.product_name, mp.unit as product_unit, mws.submit_status, sum( pass_num ) AS pass_num, sum( ng_num ) AS ng_num FROM micro_work_submit mws INNER JOIN micro_product mp ON mws.product_seq = mp.product_seq AND mws.tenant_code = mp.tenant_code
mws.submit_type = 2 AND mws.submit_status = 1
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and (mp.product_code like concat('%', #{productNameOrCode}, '%') OR mp.product_name like concat('%', #{productNameOrCode}, '%'))
GROUP BY mws.product_seq UNION ALL SELECT mws.product_seq, mp.product_code, mp.product_name, mp.unit as product_unit, mws.submit_status, sum( check_pass_num ) AS pass_num, sum( check_ng_num ) AS ng_num FROM micro_work_submit mws INNER JOIN micro_product mp ON mws.product_seq = mp.product_seq AND mws.tenant_code = mp.tenant_code
mws.submit_type = 2 AND mws.submit_status = 0
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and (mp.product_code like concat('%', #{productNameOrCode}, '%') OR mp.product_name like concat('%', #{productNameOrCode}, '%'))
GROUP BY mws.product_seq ) a GROUP BY a.product_seq ORDER BY totalNum DESC

