GROUP BY productSeq

SELECT mws.product_seq as productSeq, mp.product_code as productCode, mp.product_name as productName, mp.unit as productUnit, mws.submit_status as submitStatus, mpc.process_name as processName, mpc.process_code as processCode, mws.operate_process_seq as processSeq, sum( pass_num ) AS passNum, sum( ng_num ) AS ngNum FROM micro_work_submit mws INNER JOIN micro_product mp ON mws.product_seq = mp.product_seq AND mws.tenant_code = mp.tenant_code INNER JOIN micro_process_common mpc ON mws.operate_process_seq = mpc.process_seq AND mws.tenant_code = mp.tenant_code
mws.submit_type = 2 AND mws.submit_status = 1
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and mws.product_seq = #{productSeq}
GROUP BY mws.operate_process_seq UNION SELECT mws.product_seq as productSeq, mp.product_code as productCode, mp.product_name as productName, mp.unit as productUnit, mws.submit_status as submitStatus, mpc.process_name as processName, mpc.process_code as processCode, mws.operate_process_seq as processSeq, sum( check_pass_num ) AS passNum, sum( check_ng_num ) AS ngNum FROM micro_work_submit mws INNER JOIN micro_product mp ON mws.product_seq = mp.product_seq AND mws.tenant_code = mp.tenant_code INNER JOIN micro_process_common mpc ON mws.operate_process_seq = mpc.process_seq AND mws.tenant_code = mp.tenant_code
mws.submit_type = 2 AND mws.submit_status = 0
and mws.submit_day >= #{startDate}
