SELECT a.submitUser, a.submitNickName, a.userName, sum(a.totalNum) as totalNum FROM ( SELECT mws.submit_user as submitUser, mu.nick_name as submitNickName, mu.user_name as userName, sum(pass_num) + sum(ng_num) as totalNum FROM micro_work_submit mws INNER JOIN micro_user mu on mws.submit_user = mu.id and mws.tenant_code = mu.tenant_code
mws.submit_type = 2 and mws.submit_status = 1
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and mu.nick_name like concat('%', #{submitNickName}, '%')
GROUP BY mws.submit_user UNION SELECT mws.submit_user as submitUser, mu.nick_name as submitNickName, mu.user_name as userName, sum(check_pass_num) + sum(check_ng_num) as totalNum FROM micro_work_submit mws INNER JOIN micro_user mu on mws.submit_user = mu.id and mws.tenant_code = mu.tenant_code
mws.submit_type = 2 and mws.submit_status = 0
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and mu.nick_name like concat('%', #{submitNickName}, '%')
GROUP BY mws.submit_user ) a GROUP BY a.submitUser ORDER BY totalNum DESC

SELECT a.product_seq as productSeq, mp.product_name as productName, mp.product_code as productCode, mp.unit as productUnit, a.operate_process_seq as processSeq, mpc.process_name as processName, mpc.process_code as processCode, sum( a.pass_num ) AS passNum, sum( a.ng_num ) AS ngNum FROM ( SELECT mws.product_seq, mws.operate_process_seq, sum( check_pass_num ) AS pass_num, sum( check_ng_num ) AS ng_num, mws.tenant_code FROM micro_work_submit mws
mws.submit_type = 2 and mws.submit_status = 0
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and mws.submit_user = #{userName}
GROUP BY mws.product_seq, mws.operate_process_seq UNION SELECT mws.product_seq, mws.operate_process_seq, sum( pass_num ) AS pass_num, sum( ng_num ) AS ng_num, mws.tenant_code FROM micro_work_submit mws
mws.submit_type = 2 and mws.submit_status = 1
and mws.submit_day >= #{startDate}
and mws.submit_day <= #{endDate}
and mws.submit_user = #{userName}
GROUP BY mws.product_seq, mws.operate_process_seq ) a INNER JOIN micro_product mp ON a.product_seq = mp.product_seq AND a.tenant_code = mp.tenant_code INNER JOIN micro_process_common mpc ON a.operate_process_seq = mpc.process_seq AND a.tenant_code = mpc.tenant_code GROUP BY a.product_seq, a.operate_process_seq
